import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class Compiler_initOptions_TriageGen0Test {

  private Compiler compiler;
  private CompilerOptions options;

  @Before
  public void setUp() {
    compiler = new Compiler();
    options = new CompilerOptions();
  }

  @Test
  public void testInitOptions_DefaultErrorManager() {
    compiler.initOptions(options);
    assertNotNull(compiler.getErrorManager());
    // By default, errorManager should be initialized via LoggerErrorManager
  }

  @Test
  public void testInitOptions_WithPrintStream() {
    // When outStream is not null, it should use PrintStreamErrorManager
    compiler = new Compiler(new PrintStream(System.out));
    options.summaryDetailLevel = 1;
    compiler.initOptions(options);

    assertNotNull(compiler.getErrorManager());
    // Check if summaryDetailLevel was applied through the logic in initOptions
    // Since we can't easily check private field via standard API, we ensure no crash
  }

  @Test
  public void testInitOptions_DiagnosticGroupsOverrideCheckTypes_Enable() {
    options.enables(DiagnosticGroups.CHECK_TYPES);
    compiler.initOptions(options);
    assertTrue(options.checkTypes);
  }

  @Test
  public void testInitOptions_DiagnosticGroupsOverrideCheckTypes_Disable() {
    options.disables(DiagnosticGroups.CHECK_TYPES);
    compiler.initOptions(options);
    // checkTypes should be false
    // Note: Depending on implementation of CompilerOptions, 
    // if it's a primitive, we verify the side effect.
  }

  @Test
  public void testInitOptions_CheckTypesNotOverridden_AndFalse() {
    // Scenario: !options.checkTypes is true, and no DiagnosticGroup override
    options.checkTypes = false;
    // We need to ensure options.enables/disables for CHECK_TYPES returns false
    // This is usually the default state if not explicitly set.

    compiler.initOptions(options);

    // The code should set warning level for TYPE_PARSE_ERROR to OFF
    assertEquals(OFF, options.getWarningLevel(RhinoErrorReporter.TYPE_PARSE_ERROR));
  }

  @Test
  public void testInitOptions_CheckGlobalThisLevel_On() {
    options.checkGlobalThisLevel = CheckLevel.ERROR;
    compiler.initOptions(options);
    assertEquals(CheckLevel.ERROR, options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS));
  }

  @Test
  public void testInitOptions_CheckGlobalThisLevel_Off() {
    options.checkGlobalThisLevel = CheckLevel.OFF;
    compiler.initOptions(options);
    assertEquals(CheckLevel.OFF, options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS));
  }

  @Test
  public void testInitOptions_LanguageModeES5Strict() {
    options.setLanguageIn(LanguageMode.ECMASCRIPT5_STRICT);
    compiler.initOptions(options);
    assertEquals(ERROR, options.getWarningLevel(DiagnosticGroups.ES5_STRICT));
  }

  @Test
  public void testInitOptions_WarningsGuard_CheckVariablesEnabled() {
    // If checkSymbols is true, the if block for adding DiagnosticGroupWarningsGuard is skipped
    options.checkSymbols = true;
    compiler.initOptions(options);
    // We verify the execution completes without error
  }

  @Test
  public void testInitOptions_WarningsGuard_CheckVariablesDisabled() {
    // If checkSymbols is false AND composedGuards doesn't enable CHECK_VARIABLES
    options.checkSymbols = false;
    // We need to ensure the guard doesn't enable it. 
    // By default, it shouldn't unless specified.

    compiler.initOptions(options);
    // This tests the branch where a new DiagnosticGroupWarningsGuard is added to the composed guard
  }

  @Test
  public void testInitOptions_ExistingErrorManager() {
    ErrorManager existingManager = new LoggerErrorManager(new MessageFormatter(), new java.util.logging.Logger("test"));
    compiler.setErrorManager(existingManager);

    compiler.initOptions(options);
    // Error manager should not be overwritten if it's not null
    assertEquals(existingManager, compiler.getErrorManager());
  }
}
